function g2j(gy: number, gm: number, gday: number): JDate { let y = gy - 1600, m = gm - 1, d = gday - 1; let day = 365 * y + div(y + 3, 4) - div(y + 99, 100) + div(y + 399, 400); for (let i = 0; i < m; i++) day += gd[i + 1]; if (m > 1 && ((gy % 4 === 0 && gy % 100 !== 0) || gy % 400 === 0)) day++; day += d - 79; const np = div(day, 12053); day %= 12053; let jy = 979 + 33 * np + 4 * div(day, 1461); day %= 1461; if (day >= 366) { jy += div(day - 1, 365); day = (day - 1) % 365; } return { jy, jm: day < 186 ? 1 + div(day, 31) : 7 + div(day - 186, 30), jd: 1 + (day < 186 ? day % 31 : (day - 186) % 30) }; }
