function iso(d: Date) { return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; } function date(v: string) { const [y, m, d] = v.slice(0, 10).split('-').map(Number); return new Date(y, m - 1, d, 12); } function today() { return iso(new Date()); }
function jalali(v: string) { const d = date(v), j = g2j(d.getFullYear(), d.getMonth() + 1, d.getDate()); return `${j.jy}.${pad(j.jm)}.${pad(j.jd)}`; }
function jLeap(y: number) { const a = j2g(y + 1, 1, 1), b = j2g(y, 1, 1); return new Date(a.gy, a.gm - 1, a.gd).getTime() - new Date(b.gy, b.gm - 1, b.gd).getTime() > 365 * 86400000; }
function days(y: number, m: number) { return m < 7 ? 31 : m < 12 ? 30 : jLeap(y) ? 30 : 29; } function addJMonths(v: string, n: number) { const j = g2j(date(v).getFullYear(), date(v).getMonth() + 1, date(v).getDate()), a = j.jy * 12 + j.jm - 1 + n, y = div(a, 12), m = a % 12 + 1, g = j2g(y, m, Math.min(j.jd, days(y, m))); return `${g.gy}-${pad(g.gm)}-${pad(g.gd)}`; }
function lunar(v: string) { const [y, m, d] = v.slice(0, 10).split('-').map(Number); const parts = new Intl.DateTimeFormat('en-US-u-ca-islamic-nu-latn', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(Date.UTC(y, m - 1, d, 12))); const get = (x: string) => parts.find(p => p.type === x)?.value ?? ''; return `${get('year')}.${get('month')}.${get('day')}`; }
function reminderId(id: string) { let hash = 0; for (const char of id) hash = (Math.imul(31, hash) + char.charCodeAt(0)) | 0; return (hash >>> 0) % 2147483646 + 1; }
const INSTALLMENT_ALERTS_KEY = 'asemanian-installment-alerts';
const INSTALLMENT_IDS_KEY = 'asemanian-installment-alert-ids';
const PERSONAL_ALERTS_KEY = 'asemanian-personal-alerts-enabled';
