 useEffect(() => { if (!ready || !installmentAlertsEnabled) return; const generation = ++alertSync.current; const desired = new Map<number, { title: string; body: string; at: Date }>(); const offsets = [...new Set([0, ...(data.settings.reminderDays ?? [])])].filter(n => Number.isInteger(n) && n >= 0 && n <= 365); for (const loan of data.loans) for (const installment of loan.installments) { if (installment.status === 'paid') continue; for (const offset of offsets) { const at = dueAlertDate(installment.dueDate, offset); if (at.getTime() <= Date.now() || (!remindersAreNative() && at.getTime() - Date.now() > 20 * 86400000)) continue; desired.set(installmentAlertId(installment.id, offset), { title: offset === 0 ? `سررسید قسط ${loan.name}` : `یادآوری قسط ${loan.name}`, body: `قسط ${installment.number} · ${money(installment.amount)}${offset ? ` · ${offset} روز تا سررسید` : ' · امروز موعد پرداخت است'}`, at }); } } void (async () => { try { const previous: number[] = JSON.parse(localStorage.getItem(INSTALLMENT_IDS_KEY) || '[]'); for (const id of previous) { if (generation !== alertSync.current) return; if (!desired.has(id)) await cancelReminder(id); } for (const [id, notification] of desired) { if (generation !== alertSync.current) return; await scheduleReminder({ id, ...notification }); } if (generation === alertSync.current) localStorage.setItem(INSTALLMENT_IDS_KEY, JSON.stringify([...desired.keys()])); } catch (error) { console.error('Installment notification scheduling failed', error); setToast('تنظیم اعلان اقساط انجام نشد؛ دوباره فعال‌سازی را امتحان کنید.'); } })(); return () => { alertSync.current++; }; }, [ready, installmentAlertsEnabled, data.loans, data.settings.reminderDays, notificationTick]);
 const enableInstallmentAlerts = async () => { try { const granted = await requestReminderPermission(); if (!granted) { setToast('برای اعلان سررسید اقساط، دسترسی اعلان‌ها را در دستگاه فعال کنید.'); return; } localStorage.setItem(INSTALLMENT_ALERTS_KEY, '1'); setInstallmentAlertsEnabled(true); setToast('اعلان سررسید و یادآوری اقساط فعال شد.'); } catch (error) { console.error('Installment notification permission failed', error); setToast('فعال‌سازی اعلان‌ها انجام نشد؛ دوباره تلاش کنید.'); } };
