 const banks = [...new Set(data.loans.map(x => x.bank.trim()).filter(Boolean))]; const loanNames = [...new Set(data.loans.map(x => x.name.trim()).filter(Boolean))]; const people = [...new Set(data.ledger.map(x => x.person.trim()).filter(Boolean))]; const balance = (person: string) => data.ledger.filter(x => x.person.trim() === person && !x.settled).reduce((s, x) => s + (x.kind === 'receivable' ? x.amount : -x.amount), 0); const balances = people.map(person => ({ person, amount: balance(person) })).sort((a, b) => a.person.localeCompare(b.person, 'fa')); const ledgerTotals = balances.reduce((a, x) => ({ receivable: a.receivable + Math.max(x.amount, 0), payable: a.payable + Math.max(-x.amount, 0) }), { receivable: 0, payable: 0 });
