function IconAdd({ action, label, testId }: { action: () => void; label: string; testId: string }) { return <button data-testid={testId} onClick={action} aria-label={label} className="grid size-12 place-items-center rounded-full bg-[#1769c2] text-white shadow-lg"><Plus size={24} /></button>; }
type WeatherSource = AppSettings['weatherSource'];
const weatherSources: Record<WeatherSource, { label: string; link: string; url: string }> = {
 'open-meteo': { label: 'Open-Meteo', link: 'https://open-meteo.com/', url: 'https://api.open-meteo.com/v1/forecast?latitude=35.6892&longitude=51.3890&current=temperature_2m,weather_code&timezone=Asia%2FTehran' },
 'met-no': { label: 'MET Norway', link: 'https://www.yr.no/', url: 'https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=35.6892&lon=51.3890' },
 '7timer': { label: '7Timer', link: 'https://www.7timer.info/', url: 'https://www.7timer.info/bin/civil.php?lat=35.6892&lon=51.3890&ac=0&unit=metric&output=json' },
};
function WeatherStrip({ source }: { source: WeatherSource }) {
 const [weather, setWeather] = useState<{ temperature: number; condition: string } | null>(null);
 const [error, setError] = useState(false);
 const [retry, setRetry] = useState(0);
 useEffect(() => {
  const controller = new AbortController(); setWeather(null); setError(false);
  fetch(weatherSources[source].url, { signal: controller.signal }).then(r => { if (!r.ok) throw Error('weather unavailable'); return r.json(); }).then((result: any) => {
   let temperature: number; let condition: string;
   if (source === 'open-meteo') { temperature = result.current?.temperature_2m; const code = result.current?.weather_code; condition = code === 0 ? 'آفتابی' : code <= 3 ? 'نیمه‌ابری' : code <= 48 ? 'مه‌آلود' : code <= 67 ? 'بارانی' : code <= 77 ? 'برفی' : code <= 82 ? 'رگبار' : 'ابری'; }
   else if (source === 'met-no') { const entry = result.properties?.timeseries?.[0]?.data; temperature = entry?.instant?.details?.air_temperature; const symbol = String(entry?.next_1_hours?.summary?.symbol_code ?? ''); condition = symbol.includes('snow') ? 'برفی' : symbol.includes('rain') || symbol.includes('showers') ? 'بارانی' : symbol.includes('cloud') ? 'ابری' : symbol.includes('fog') ? 'مه‌آلود' : 'آفتابی'; }
   else { const entry = result.dataseries?.[0]; temperature = entry?.temp2m; const symbol = String(entry?.weather ?? ''); condition = symbol.includes('snow') ? 'برفی' : symbol.includes('rain') || symbol.includes('shower') ? 'بارانی' : symbol.includes('cloud') ? 'ابری' : 'آفتابی'; }
   if (!Number.isFinite(temperature)) throw Error('missing weather'); setWeather({ temperature, condition });
  }).catch(() => { if (!controller.signal.aborted) setError(true); });
  return () => controller.abort();
 }, [source, retry]);
 const Icon = weather?.condition === 'آفتابی' ? Sun : weather?.condition === 'بارانی' ? CloudRain : weather?.condition === 'نیمه‌ابری' ? CloudSun : Cloud;
 return <div data-testid="report-weather" className="flex min-h-12 flex-wrap items-center gap-3 rounded-2xl border border-slate-200 bg-white px-4 py-2 text-sm shadow-sm dark:border-slate-700 dark:bg-[#162235]"><Icon size={18} className="text-[#1769c2]" /><b>هوای تهران</b>{weather ? <span data-testid="weather-current">{Math.round(weather.temperature)}° · {weather.condition}</span> : error ? <span data-testid="weather-error">هواشناسی در دسترس نیست <button data-testid="weather-retry" onClick={() => setRetry(n => n + 1)} className="min-h-10 px-2 text-[#1769c2]">تلاش دوباره</button></span> : <span data-testid="weather-loading" className="text-slate-500">در حال دریافت هوا…</span>}</div>;
}
function Dashboard({ totals, loans, go, showWeather }: { totals: { total: number; paid: number; remaining: number; overdue: number }; loans: Loan[]; go: () => void; showWeather: boolean }) { const progress = totals.total ? Math.round(totals.paid / totals.total * 100) : 0; const next = loans.flatMap(loan => loan.installments.filter(i => i.status !== 'paid').map(i => ({ ...i, loan }))).filter(i => i.dueDate >= today()).sort((a, b) => a.dueDate.localeCompare(b.dueDate))[0]; const now = date(today()), solarDay = g2j(now.getFullYear(), now.getMonth() + 1, now.getDate()); const [, lunarMonth, lunarDay] = lunar(today()).split('.').map(Number); const occasions = iranOccasions(solarDay.jm, solarDay.jd, lunarMonth, lunarDay); return <div className="space-y-4">{showWeather && <WeatherStrip source="open-meteo" />}<div className="grid grid-cols-1 gap-3 sm:grid-cols-2"><Card><small className="text-slate-500">اولین قسط پیش رو</small>{next ? <div data-testid="dashboard-next-installment" className="mt-2"><b className="block text-lg">{next.loan.name}</b><p className="mt-1 text-sm text-slate-500">{jalali(next.dueDate)} · {money(next.amount)}</p></div> : <p data-testid="dashboard-next-installment" className="mt-2 text-sm text-slate-500">قسط پیش رویی ثبت نشده است.</p>}</Card><Card><small className="text-slate-500">مناسبت امروز · {jalali(today())}</small><div data-testid="dashboard-today-occasions" className="mt-2 space-y-1">{now.getDay() === 5 && <p className="text-sm font-medium text-rose-600">جمعه · تعطیل هفتگی</p>}{occasions.map((event, index) => <p key={index} className={`text-sm font-medium ${event.holiday ? 'text-rose-600' : 'text-violet-600 dark:text-violet-400'}`}>{event.title}{event.holiday ? ' · تعطیل' : ''}</p>)}{now.getDay() !== 5 && !occasions.length && <p className="text-sm text-slate-500">مناسبتی برای امروز ثبت نشده است.</p>}</div></Card></div><div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">{[['مانده کل', money(totals.remaining), 'text-[#1769c2]'], ['پرداخت‌شده', money(totals.paid), 'text-emerald-600'], ['اقساط معوق', num(totals.overdue), 'text-rose-600'], ['تعداد وام‌ها', num(loans.length), 'text-violet-600']].map(x => <Card key={x[0]}><small className="text-slate-500">{x[0]}</small><b className={`mt-2 block text-xl ${x[2]}`}>{x[1]}</b></Card>)}</div><Card><div className="flex justify-between"><b>پیشرفت بازپرداخت</b><b>{num(progress)}%</b></div><div className="mt-3 h-3 overflow-hidden rounded-full bg-slate-100"><div className="h-full bg-[#1769c2]" style={{ width: `${progress}%` }} /></div></Card>{!loans.length && <Card><div className="py-7 text-center"><b>هنوز وامی ثبت نشده است</b><button onClick={go} className="mx-auto mt-4 block rounded-xl bg-[#1769c2] px-4 py-2 text-white">ثبت وام</button></div></Card>}</div>; }
function Loans({ loans, q, setQ, sort, showSettled, setSort, setShowSettled, edit, remove }: { loans: Loan[]; q: string; setQ: (v: string) => void; sort: AppSettings['loanSort']; showSettled: boolean; setSort: (v: AppSettings['loanSort']) => void; setShowSettled: (v: boolean) => void; edit: (l: Loan) => void; remove: (l: Loan) => void }) { const remaining = (loan: Loan) => loan.installments.filter(i => i.status !== 'paid').reduce((s, i) => s + i.amount, 0); const shown = loans.filter(x => (!q || `${x.name} ${x.bank}`.toLowerCase().includes(q.toLowerCase())) && (showSettled || remaining(x) > 0)).sort((a, b) => sort === 'name' ? a.name.localeCompare(b.name, 'fa') : sort === 'remaining' ? remaining(b) - remaining(a) : sort === 'oldest' ? a.createdAt.localeCompare(b.createdAt) : b.createdAt.localeCompare(a.createdAt)); return <div className="space-y-3"><label className="relative block"><Search className="absolute right-3 top-3 text-slate-400" size={18} /><input data-testid="loan-search" value={q} onChange={e => setQ(e.target.value)} className="min-h-11 w-full rounded-xl bg-white ps-10 pe-3 dark:bg-[#162235]" placeholder="جست‌وجوی نام و بانک" /></label><div className="flex flex-wrap items-center justify-between gap-2"><label className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-300">ترتیب نمایش<select data-testid="loan-sort" value={sort} onChange={e => setSort(e.target.value as AppSettings['loanSort'])} className="min-h-11 rounded-xl border border-slate-200 bg-white px-2 dark:border-slate-700 dark:bg-[#162235]"><option value="newest">جدیدترین</option><option value="oldest">قدیمی‌ترین</option><option value="name">نام وام</option><option value="remaining">بیشترین مانده</option></select></label><label className="flex min-h-11 items-center gap-2 text-sm"><input data-testid="show-settled-loans" type="checkbox" checked={showSettled} onChange={e => setShowSettled(e.target.checked)} className="size-5 accent-[#1769c2]" />نمایش وام‌های تسویه‌شده</label></div>{shown.map(loan => { const paid = loan.installments.filter(i => i.status === 'paid').length, left = remaining(loan); return <Card key={loan.id} className="!p-0"><div className="flex items-center gap-1 px-3 py-2 sm:px-4"><button data-testid={`loan-${loan.id}`} onClick={() => edit(loan)} className="min-w-0 flex-1 rounded-xl p-1.5 text-right hover:bg-slate-50 focus-visible:outline-2 focus-visible:outline-[#1769c2] dark:hover:bg-slate-800"><div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1"><b className="min-w-0 truncate text-base">{loan.name}</b><span className="text-xs text-slate-500">{paid} از {loan.installments.length} قسط پرداخت‌شده</span></div><div className="mt-1 flex flex-wrap items-center justify-between gap-x-4 gap-y-1 text-xs text-slate-500 sm:text-sm"><span>هر قسط {money(loan.installmentAmount)}</span><span className="font-semibold text-[#1769c2] dark:text-blue-400">مانده {money(left)}</span></div></button><button data-testid={`delete-loan-${loan.id}`} onClick={() => remove(loan)} aria-label={`حذف وام ${loan.name}`} className="grid size-11 shrink-0 place-items-center rounded-xl text-slate-400 hover:bg-rose-50 hover:text-rose-600 focus-visible:outline-2 dark:hover:bg-slate-800"><Trash2 size={17} /></button></div></Card>; })}{!shown.length && <Card><p className="py-10 text-center text-slate-500">{loans.length ? 'وامی با این فیلتر پیدا نشد.' : 'هنوز وامی ثبت نشده است.'}</p></Card>}</div>; }
function LoanModal({ loan, banks, loanNames, close, save }: { loan: Loan | null; banks: string[]; loanNames: string[]; close: () => void; save: (v: Loan) => void }) { const [form, setForm] = useState<Loan>(loan || { id: uid(), name: '', bank: '', totalAmount: 0, installmentAmount: 0, installmentCount: 0, firstDate: today(), frequency: 'monthly', notes: '', createdAt: new Date().toISOString(), installments: [] }); const [error, setError] = useState(''); const set = <K extends keyof Loan>(k: K, v: Loan[K]) => setForm({ ...form, [k]: v }); const submit = () => { if (!form.name.trim() || !form.bank.trim() || !form.totalAmount || !form.installmentAmount || !form.installmentCount) return setError('همهٔ موارد ضروری را کامل وارد کنید.'); save({ ...form, name: form.name.trim(), bank: form.bank.trim(), installments: loan ? form.installments : makeInstallments(form.firstDate, form.installmentCount, form.installmentAmount, form.frequency) }); }; return <div className="fixed inset-0 z-30 overflow-y-auto bg-slate-950/45 p-3"><div className="mx-auto my-5 w-full max-w-3xl rounded-2xl bg-white p-5 dark:bg-[#162235]"><div className="flex justify-between"><b>{loan ? 'جزئیات وام و اقساط' : 'ثبت وام جدید'}</b><button onClick={close}><X /></button></div><div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2"><label className="text-sm">نام وام<input data-testid="loan-name" list="saved-loan-names" value={form.name} onChange={e => set('name', e.target.value)} className="mt-1 min-h-11 w-full rounded-xl border p-3 dark:bg-slate-800" /><datalist id="saved-loan-names">{loanNames.map(x => <option key={x} value={x} />)}</datalist></label><label className="text-sm">نام بانک<input data-testid="loan-bank" list="saved-banks" value={form.bank} onChange={e => set('bank', e.target.value)} className="mt-1 min-h-11 w-full rounded-xl border p-3 dark:bg-slate-800" /><datalist id="saved-banks">{banks.map(x => <option key={x} value={x} />)}</datalist></label><label className="text-sm">مبلغ کل<NumericInput testId="loan-totalAmount" value={form.totalAmount} onChange={v => set('totalAmount', v)} /></label><label className="text-sm">مبلغ قسط<NumericInput testId="loan-installmentAmount" value={form.installmentAmount} onChange={v => set('installmentAmount', v)} /></label><label className="text-sm">تعداد اقساط<NumericInput testId="loan-installmentCount" value={form.installmentCount} unit={false} onChange={v => set('installmentCount', v)} /></label><label><JalaliInput label="تاریخ اولین قسط" value={form.firstDate} change={v => set('firstDate', v)} /></label><label className="text-sm">تناوب<select value={form.frequency} onChange={e => set('frequency', e.target.value as Frequency)} className="mt-1 min-h-11 w-full rounded-xl border p-3 dark:bg-slate-800"><option value="monthly">ماهانه</option><option value="every2months">هر ۲ ماه</option><option value="quarterly">هر ۳ ماه</option></select></label></div>{error && <p className="mt-3 text-sm text-rose-600">{error}</p>}{loan && <div className="mt-5 space-y-2 border-t pt-4">{form.installments.map(i => <div key={i.id} className="flex items-center justify-between rounded-xl bg-slate-50 p-3 dark:bg-slate-800"><span>قسط {num(i.number)} · <span dir="ltr">{jalali(i.dueDate)}</span></span><div className="flex items-center gap-3"><b>{money(i.amount)}</b><button data-testid={`installment-toggle-${i.number}`} onClick={() => set('installments', form.installments.map(x => x.id === i.id ? { ...x, status: x.status === 'paid' ? 'unpaid' : 'paid', paymentDate: x.status === 'paid' ? undefined : today() } : x))} className={`grid size-10 place-items-center rounded-full ${i.status === 'paid' ? 'bg-emerald-600 text-white' : 'border-2 border-slate-300'}`}><Check size={18} /></button></div></div>)}</div>}<button data-testid="save-loan" onClick={submit} className="mt-5 rounded-xl bg-[#1769c2] px-5 py-3 text-white">ذخیره</button></div></div>; }
function Calendar({ month, setMonth, items, reminders, reminderDays, installmentAlertsEnabled, enableInstallmentAlerts, saveReminder, deleteReminder, selected, setSelected, kind, toggle }: { month: { y: number; m: number }; setMonth: React.Dispatch<React.SetStateAction<{ y: number; m: number }>>; items: Array<Installment & { loan: Loan }>; reminders: Reminder[]; reminderDays: number[]; installmentAlertsEnabled: boolean; enableInstallmentAlerts: () => void; saveReminder: (r: Reminder) => void; deleteReminder: (id: string) => void; selected: string; setSelected: (v: string) => void; kind: CalendarKind; toggle: (l: Loan, i: Installment) => void }) {
 const [editing, setEditing] = useState<Reminder | null | false>(false);
 const first = j2g(month.y, month.m, 1);
 const offset = (new Date(first.gy, first.gm - 1, first.gd).getDay() + 1) % 7;
 const cells = useMemo(() => Array.from({ length: days(month.y, month.m) }, (_, i) => { const g = j2g(month.y, month.m, i + 1); const dayIso = `${g.gy}-${pad(g.gm)}-${pad(g.gd)}`; const [, lm, ld] = lunar(dayIso).split('.').map(Number); return { day: i + 1, iso: dayIso, friday: new Date(g.gy, g.gm - 1, g.gd).getDay() === 5, occasions: iranOccasions(month.m, i + 1, lm, ld) }; }), [month.y, month.m]);
 const dueByDate = useMemo(() => { const result = new Map<string, Array<Installment & { loan: Loan }>>(); items.forEach(item => result.set(item.dueDate, [...(result.get(item.dueDate) ?? []), item])); return result; }, [items]);
 const alertsByDate = useMemo(() => { const result = new Map<string, Array<{ item: Installment & { loan: Loan }; daysBefore: number }>>(); const offsets = [...new Set(Array.isArray(reminderDays) ? reminderDays.filter(n => Number.isInteger(n) && n > 0 && n <= 365) : [])]; items.filter(i => i.status !== 'paid').forEach(item => offsets.forEach(n => { const d = date(item.dueDate); d.setDate(d.getDate() - n); const key = iso(d); result.set(key, [...(result.get(key) ?? []), { item, daysBefore: n }]); })); return result; }, [items, reminderDays]);
 const selectedCell = cells.find(c => c.iso === selected);
 const chosenOccasions: Occasion[] = selectedCell?.occasions ?? (() => { const d = date(selected), s = g2j(d.getFullYear(), d.getMonth() + 1, d.getDate()), [, lm, ld] = lunar(selected).split('.').map(Number); return iranOccasions(s.jm, s.jd, lm, ld); })();
 const chosenDue = dueByDate.get(selected) ?? [];
 const chosenAlerts = alertsByDate.get(selected) ?? [];
 const chosenReminders = reminders.filter(r => r.date === selected);
 const move = (n: number) => { const a = month.y * 12 + month.m - 1 + n, y = div(a, 12), m = a % 12 + 1, g = j2g(y, m, 1); setMonth({ y, m }); setSelected(`${g.gy}-${pad(g.gm)}-${pad(g.gd)}`); };
 return <div className="space-y-4"><Card className="!p-3 sm:!p-5"><div className="flex items-center justify-between px-1"><button data-testid="calendar-next" aria-label="ماه قبل" onClick={() => move(-1)} className="grid size-11 place-items-center rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800"><ChevronRight size={20} /></button><b className="text-lg">{months[month.m - 1]} {month.y}</b><button data-testid="calendar-prev" aria-label="ماه بعد" onClick={() => move(1)} className="grid size-11 place-items-center rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800"><ChevronLeft size={20} /></button></div><div className="mt-4 grid grid-cols-7 gap-1 text-center text-xs text-slate-500">{weekdays.map(x => <b key={x} className={x === 'ج' ? 'text-rose-600' : ''}>{x}</b>)}</div><div className="mt-2 grid grid-cols-7 gap-1">{Array.from({ length: offset }).map((_, i) => <i key={i} />)}{cells.map(c => { const hasDue = (dueByDate.get(c.iso)?.length ?? 0) > 0, hasReminder = (alertsByDate.get(c.iso)?.length ?? 0) > 0 || reminders.some(r => r.date === c.iso), hasHoliday = c.friday || c.occasions.some(o => o.holiday), hasOccasion = c.occasions.some(o => !o.holiday); return <button data-testid={`calendar-day-${c.iso}`} aria-label={`${jalali(c.iso)}${hasHoliday ? '، تعطیل' : ''}${hasOccasion ? '، مناسبت' : ''}${hasDue ? '، قسط' : ''}${hasReminder ? '، یادآور' : ''}`} key={c.iso} onClick={() => setSelected(c.iso)} className={`flex min-h-16 min-w-0 flex-col items-center justify-start rounded-xl border px-0.5 py-2 text-xs transition-colors hover:bg-slate-50 focus-visible:outline-2 focus-visible:outline-[#1769c2] dark:hover:bg-slate-800 ${selected === c.iso ? 'border-[#1769c2] bg-blue-50 dark:bg-blue-950' : 'border-slate-100 dark:border-slate-700'}`}><b className={hasHoliday ? 'text-rose-600 dark:text-rose-400' : hasOccasion ? 'text-violet-600 dark:text-violet-400' : ''}>{c.day}</b>{kind === 'lunar' && <small dir="ltr" className="mt-0.5 block text-[10px] text-slate-500">{lunar(c.iso).slice(-5)}</small>}{kind === 'gregorian' && <small dir="ltr" className="mt-0.5 block text-[10px] text-slate-500">{c.iso.slice(5).replace('-', '.')}</small>}<span className="mt-auto flex min-h-2.5 items-center justify-center gap-0.5 pt-1">{hasHoliday && <i data-testid={`calendar-holiday-dot-${c.iso}`} className="size-2 rounded-full bg-rose-500" />}{hasOccasion && <i data-testid={`calendar-occasion-dot-${c.iso}`} className="size-2 rounded-full bg-violet-500" />}{hasDue && <i data-testid={`calendar-loan-dot-${c.iso}`} className="size-2 rounded-full bg-[#1769c2]" />}{hasReminder && <i data-testid={`calendar-reminder-dot-${c.iso}`} className="size-2 rounded-full bg-amber-500" />}</span></button>; })}</div><div className="mt-4 flex flex-wrap gap-x-4 gap-y-1 border-t border-slate-100 pt-3 text-xs text-slate-500 dark:border-slate-700"><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-rose-500" />تعطیلی</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-violet-500" />مناسبت</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-[#1769c2]" />قسط وام</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-amber-500" />یادآور</span></div></Card>
 <Card><div className="flex flex-wrap items-center justify-between gap-2"><div><b data-testid="calendar-selected-date">{jalali(selected)}</b><p className="mt-1 text-sm text-slate-500">رویدادهای این روز</p></div><button data-testid="add-reminder" onClick={() => setEditing(null)} className="flex min-h-11 items-center gap-2 rounded-xl bg-[#1769c2] px-3 text-sm font-bold text-white hover:bg-blue-700"><Plus size={17} />یادآور جدید</button></div><button data-testid="enable-installment-alerts" onClick={enableInstallmentAlerts} className="mt-3 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl border border-[#1769c2] px-3 text-sm font-semibold text-[#1769c2] hover:bg-blue-50 dark:hover:bg-slate-800"><Bell size={17} />{installmentAlertsEnabled ? 'اعلان اقساط فعال است · تنظیم دوباره' : 'فعال‌سازی اعلان سررسید اقساط'}</button><div className="mt-4 space-y-2">{selectedCell?.friday && <div className="rounded-xl bg-rose-50 px-3 py-3 text-sm text-rose-700 dark:bg-rose-950/30 dark:text-rose-300">روز جمعه · تعطیل هفتگی</div>}{chosenOccasions.map((event, index) => <div key={`occasion-${index}`} data-testid={`calendar-occasion-${index}`} className={`flex items-center gap-2 rounded-xl px-3 py-3 text-sm ${event.holiday ? 'bg-rose-50 text-rose-700 dark:bg-rose-950/30 dark:text-rose-300' : 'bg-violet-50 text-violet-700 dark:bg-violet-950/30 dark:text-violet-300'}`}><span className={`size-2 shrink-0 rounded-full ${event.holiday ? 'bg-rose-500' : 'bg-violet-500'}`} />{event.title}{event.holiday && <span className="ms-auto text-xs">تعطیل</span>}</div>)}{chosenDue.map(i => <div key={`due-${i.id}`} className="flex items-center gap-3 rounded-xl bg-slate-50 p-3 dark:bg-slate-800"><span className="size-2 shrink-0 rounded-full bg-[#1769c2]" /><div className="min-w-0 flex-1"><b className="text-sm">قسط {i.loan.name}</b><p className="text-sm text-slate-500">قسط {num(i.number)} · {money(i.amount)}{i.status === 'paid' ? ' · پرداخت‌شده' : ''}</p></div><button data-testid={`calendar-installment-${i.id}`} aria-label={i.status === 'paid' ? 'بازگشت به پرداخت‌نشده' : 'ثبت پرداخت قسط'} onClick={() => toggle(i.loan, i)} className={`grid size-11 shrink-0 place-items-center rounded-full ${i.status === 'paid' ? 'bg-emerald-600 text-white' : 'border-2 border-slate-300 dark:border-slate-600'}`}><Check size={18} /></button></div>)}{chosenAlerts.map(({ item, daysBefore }) => <div key={`alert-${item.id}-${daysBefore}`} className="flex items-center gap-3 rounded-xl bg-amber-50 p-3 text-sm dark:bg-amber-950/20"><Bell size={17} className="shrink-0 text-amber-600" /><span>یادآور قسط {item.loan.name} · {num(daysBefore)} روز تا سررسید</span></div>)}{chosenReminders.map(r => <div key={r.id} className="flex items-center gap-2 rounded-xl bg-amber-50 p-3 dark:bg-amber-950/20"><Bell size={17} className="shrink-0 text-amber-600" /><div className="min-w-0 flex-1"><b className="text-sm">{r.title}</b>{r.time && <span dir="ltr" className="ms-2 rounded-full bg-white px-2 py-0.5 text-xs font-bold tabular-nums text-amber-700 dark:bg-slate-800 dark:text-amber-300">{r.time}</span>}{r.notes && <p className="mt-1 break-words text-sm text-slate-500">{r.notes}</p>}</div><button data-testid={`edit-reminder-${r.id}`} aria-label={`ویرایش ${r.title}`} onClick={() => setEditing(r)} className="grid size-11 shrink-0 place-items-center rounded-xl hover:bg-amber-100 dark:hover:bg-slate-800"><Pencil size={17} /></button><button data-testid={`delete-reminder-${r.id}`} aria-label={`حذف ${r.title}`} onClick={() => { if (confirm('این یادآور حذف شود؟')) deleteReminder(r.id); }} className="grid size-11 shrink-0 place-items-center rounded-xl text-rose-600 hover:bg-rose-100 dark:hover:bg-slate-800"><Trash2 size={17} /></button></div>)}{!selectedCell?.friday && !chosenOccasions.length && !chosenDue.length && !chosenAlerts.length && !chosenReminders.length && <p className="py-6 text-center text-sm text-slate-500">برای این روز رویدادی ثبت نشده است.</p>}</div><p className="mt-4 text-xs leading-6 text-slate-500">مناسبت‌های قمری بر پایهٔ محاسبه‌اند و ممکن است با اعلام رسمی یک روز اختلاف داشته باشند.</p></Card>{editing !== false && <ReminderModal key={editing?.id ?? `new-${selected}`} reminder={editing} selected={selected} close={() => setEditing(false)} save={r => { saveReminder(r); setEditing(false); const d = date(r.date), j = g2j(d.getFullYear(), d.getMonth() + 1, d.getDate()); setMonth({ y: j.jy, m: j.jm }); setSelected(r.date); }} />}</div>;
}
function ReminderModal({ reminder, selected, close, save }: { reminder: Reminder | null; selected: string; close: () => void; save: (r: Reminder) => void }) { const [form, setForm] = useState<Reminder>(() => reminder ? { ...reminder, time: reminder.time || '09:00' } : { id: uid(), title: '', ...nextReminderDateTime(selected < today() ? today() : selected), notes: '' }); const future = new Date(`${form.date}T${form.time || '09:00'}:00`).getTime() > Date.now(); return <div className="fixed inset-0 z-40 overflow-y-auto bg-slate-950/50 p-3"><div className="mx-auto my-4 w-full max-w-md rounded-2xl bg-white p-5 dark:bg-[#162235]"><div className="flex items-center justify-between"><b>{reminder ? 'ویرایش یادآور' : 'یادآور جدید'}</b><button data-testid="close-reminder" aria-label="بستن" onClick={close} className="grid size-11 place-items-center rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800"><X size={20} /></button></div><div className="mt-4 space-y-4"><label className="block text-sm">عنوان<input data-testid="reminder-title" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="مثلاً پیگیری پرداخت" className="mt-1 min-h-11 w-full rounded-xl border border-slate-200 bg-white px-3 dark:border-slate-700 dark:bg-slate-800" /></label><div><JalaliInput label="تاریخ یادآور" value={form.date} change={v => setForm({ ...form, date: v })} /></div><ClockPicker value={form.time || '09:00'} onChange={time => setForm({ ...form, time })} /><p className="text-xs text-slate-500">{remindersAreNative() ? 'در نسخه نصب‌شده، اعلان حتی وقتی برنامه بسته است نمایش داده می‌شود.' : 'در مرورگر، اعلان فقط هنگام باز بودن برنامه نمایش داده می‌شود.'}</p><label className="block text-sm">توضیحات (اختیاری)<textarea data-testid="reminder-notes" value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} className="mt-1 min-h-20 w-full rounded-xl border border-slate-200 bg-white p-3 dark:border-slate-700 dark:bg-slate-800" /></label></div>{!future && <p className="mt-3 text-sm text-rose-600">برای دریافت اعلان، تاریخ و ساعتی در آینده انتخاب کنید.</p>}<button data-testid="save-reminder" disabled={!form.title.trim() || !future} onClick={() => save({ ...form, title: form.title.trim(), notes: form.notes.trim() })} className="mt-5 min-h-11 w-full rounded-xl bg-[#1769c2] font-bold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50">ذخیره یادآور</button></div></div>; }
function Reports({ totals, rows, paidColor, remainingColor, showWeather, weatherSource, setWeatherSettings }: { totals: { total: number; paid: number; remaining: number; paidCount: number; overdue: number }; rows: Array<{ month: string; due: number; paid: number }>; paidColor: string; remainingColor: string; showWeather: boolean; weatherSource: WeatherSource; setWeatherSettings: (changes: Partial<AppSettings>) => void }) { const current = jalali(today()).slice(0, 7), shown = rows.filter(x => x.month === current), chart = shown.length ? shown : [{ month: current, due: 0, paid: 0 }], max = Math.max(1, ...chart.map(x => x.due)); return <div className="space-y-4">{showWeather && <WeatherStrip source={weatherSource} />}<Card className="!py-3"><div className="flex flex-wrap items-center gap-3"><label className="flex min-h-11 items-center gap-2 text-sm"><input data-testid="settings-show-weather" type="checkbox" checked={showWeather} onChange={e => setWeatherSettings({ showWeather: e.target.checked })} className="size-5 accent-[#1769c2]" />نمایش هواشناسی</label><label className="flex min-h-11 items-center gap-2 text-sm">مرجع هواشناسی<select data-testid="weather-source-select" value={weatherSource} onChange={e => setWeatherSettings({ weatherSource: e.target.value as WeatherSource })} className="min-h-11 rounded-xl border border-slate-200 bg-white px-2 dark:border-slate-700 dark:bg-slate-800">{Object.entries(weatherSources).map(([key, value]) => <option key={key} value={key}>{value.label}</option>)}</select></label><a data-testid="weather-source-link" href={weatherSources[weatherSource].link} target="_blank" rel="noopener noreferrer" className="ms-auto text-sm text-[#1769c2] underline">مشاهده مرجع</a></div></Card><div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">{([['کل وام‌ها', totals.total], ['کل پرداختی', totals.paid], ['کل مانده', totals.remaining], ['اقساط پرداختی', totals.paidCount], ['اقساط معوق', totals.overdue]] as Array<[string, number]>).map(x => <Card key={x[0]}><small className="text-slate-500">{x[0]}</small><b className="mt-2 block text-lg">{x[0].includes('اقساط') ? num(x[1]) : money(x[1])}</b></Card>)}</div><Card><div className="flex items-center justify-between"><b>تعهد و پرداخت ماهانه</b><small>ماه جاری</small></div><div className="mt-5 flex h-44 items-end gap-6">{chart.map(r => <div key={r.month} className="flex flex-1 items-end justify-center gap-3"><div className="flex flex-col items-center gap-2"><i className="w-12 rounded-t" style={{ height: `${Math.max(4, r.due / max * 120)}px`, background: remainingColor }} /><small>تعهد</small></div><div className="flex flex-col items-center gap-2"><i className="w-12 rounded-t" style={{ height: `${Math.max(4, r.paid / max * 120)}px`, background: paidColor }} /><small>پرداخت</small></div></div>)}</div></Card><Card><div className="flex justify-between"><b>پیشرفت بازپرداخت</b><b>{num(totals.total ? Math.round(totals.paid / totals.total * 100) : 0)}٪</b></div><div className="mt-3 h-3 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-700"><div className="h-full rounded-full bg-[#1769c2]" style={{ width: `${Math.min(100, totals.total ? Math.round(totals.paid / totals.total * 100) : 0)}%` }} /></div></Card></div>; }
function Ledger({ entries, balances, totals, person, select, edit, remove, settle }: { entries: LedgerEntry[]; balances: Array<{ person: string; amount: number }>; totals: { receivable: number; payable: number }; person: string | null; select: (x: string | null) => void; edit: (x: LedgerEntry | null) => void; remove: (x: LedgerEntry) => void; settle: (x: string) => void }) { if (person) { const list = entries.filter(x => x.person.trim() === person).sort((a, b) => b.date.localeCompare(a.date)); const amount = balances.find(x => x.person === person)?.amount || 0; return <div className="space-y-3"><Card><span className="text-sm text-slate-500">اختلاف طلب و بدهی این حساب</span><div className="mt-1 flex flex-wrap items-center justify-between gap-2"><b className={amount > 0 ? 'text-emerald-600' : amount < 0 ? 'text-rose-600' : 'text-slate-600'}>{balanceLabel(amount)}</b><b data-testid="person-balance" className="text-lg" dir="ltr">{money(Math.abs(amount))}</b></div></Card><div className="flex items-center gap-3"><IconAdd testId="add-person-entry" label="ثبت گردش جدید برای این شخص" action={() => edit(null)} /><span className="text-sm text-slate-500">گردش جدید</span></div><div className="space-y-2">{list.map(x => <Card key={x.id} className="!p-0"><div className="flex items-center gap-1 p-2"><button data-testid={`ledger-entry-${x.id}`} onClick={() => edit(x)} className="min-w-0 flex-1 rounded-xl p-2 text-right hover:bg-slate-50 focus-visible:outline-2 dark:hover:bg-slate-800"><div className="flex flex-wrap items-center justify-between gap-1"><b className={x.kind === 'receivable' ? 'text-emerald-600' : 'text-rose-600'}>{x.movement === 'received' ? 'دریافت کردم' : x.movement === 'paid' ? 'پرداخت کردم' : x.notes.startsWith('تسویه:') ? x.notes.slice(6).trim() : x.kind === 'receivable' ? 'طلب من' : 'بدهی من'} · {money(x.amount)}</b><span dir="ltr" className="text-sm text-slate-500">{jalali(x.date)}</span></div>{x.notes && !x.notes.startsWith('تسویه:') && <small className="mt-1 block truncate text-slate-500">{x.notes}</small>}</button><button data-testid={`delete-entry-${x.id}`} onClick={() => remove(x)} aria-label="حذف گردش" className="grid size-11 shrink-0 place-items-center rounded-xl text-rose-500 hover:bg-rose-50"><Trash2 size={18} /></button></div></Card>)}{!list.length && <Card><p className="py-6 text-center text-slate-500">گردش مالی برای این شخص ثبت نشده است.</p></Card>}</div>{amount !== 0 && <button data-testid="settle-person" onClick={() => settle(person)} className="min-h-11 w-full rounded-xl border border-[#1769c2] font-bold text-[#1769c2]">تسویه شد</button>}</div>; } return <div className="space-y-4"><Card><small>تراز دفتر</small><b data-testid="ledger-net-balance" className={`mt-2 block ${totals.receivable - totals.payable >= 0 ? 'text-[#1769c2]' : 'text-rose-600'}`}>{money(totals.receivable - totals.payable)}</b></Card><div className="grid grid-cols-1 gap-3 sm:grid-cols-2"><Card><small>طلب من از اشخاص</small><b className="mt-2 block text-emerald-600">{money(totals.receivable)}</b></Card><Card><small>بدهی به اشخاص</small><b className="mt-2 block text-rose-600">{money(totals.payable)}</b></Card></div><Card className="!p-0">{balances.map(x => <button key={x.person} data-testid={`person-${x.person}`} onClick={() => select(x.person)} className="flex min-h-16 w-full items-center justify-between gap-3 border-b border-slate-100 px-4 text-right last:border-0 hover:bg-slate-50 focus-visible:outline-2 dark:border-slate-700 dark:hover:bg-slate-800"><b className="min-w-0 truncate">{x.person}</b><span data-testid={`balance-${x.person}`} className={`shrink-0 text-sm ${x.amount > 0 ? 'text-emerald-600' : x.amount < 0 ? 'text-rose-600' : 'text-slate-500'}`}>{balanceLabel(x.amount)} · {money(Math.abs(x.amount))}</span></button>)}{!balances.length && <p className="p-10 text-center text-slate-500">هنوز شخصی در دفتر ثبت نشده است.</p>}</Card></div>; }
function balanceLabel(amount: number) { return amount > 0 ? 'طلب من' : amount < 0 ? 'بدهی من' : 'تسویه'; }
function EntryModal({ entry, people, initialPerson, close, save }: { entry: LedgerEntry | null; people: string[]; initialPerson: string | null; close: () => void; save: (e: LedgerEntry) => void }) { const [form, setForm] = useState<LedgerEntry>(entry || { id: uid(), person: initialPerson || '', kind: 'receivable', amount: 0, date: today(), notes: '', settled: false }); return <div className="fixed inset-0 z-30 overflow-y-auto bg-slate-950/45 p-3"><div className="mx-auto my-4 w-full max-w-md rounded-2xl bg-white p-5 dark:bg-[#162235]"><div className="flex justify-between"><b>ثبت در دفتر</b><button onClick={close}><X /></button></div><div className="mt-4 space-y-3"><label className="block text-sm">نام شخص<input data-testid="ledger-person" list="saved-people" value={form.person} onChange={e => setForm({ ...form, person: e.target.value })} className="mt-1 min-h-11 w-full rounded-xl border p-3 dark:bg-slate-800" /><datalist id="saved-people">{people.map(x => <option key={x} value={x} />)}</datalist></label><select data-testid="ledger-kind" value={form.kind} onChange={e => setForm({ ...form, kind: e.target.value as LedgerEntry['kind'], movement: undefined })} className="min-h-11 w-full rounded-xl border p-3 dark:bg-slate-800"><option value="receivable">طلب من</option><option value="payable">بدهی من</option></select><NumericInput testId="ledger-amount" value={form.amount} onChange={amount => setForm({ ...form, amount })} placeholder="مبلغ" /><JalaliInput label="تاریخ" value={form.date} change={date => setForm({ ...form, date })} /><textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="یادداشت" className="min-h-20 w-full rounded-xl border p-3 dark:bg-slate-800" /></div><button data-testid="save-ledger" disabled={!form.person.trim() || form.amount <= 0} onClick={() => save({ ...form, person: form.person.trim() })} className="mt-5 min-h-12 w-full rounded-xl bg-[#1769c2] py-3 font-bold text-white hover:bg-blue-700 disabled:opacity-50">ذخیره گردش در دفتر</button></div></div>; }
function SettlementModal({ person, balance, close, save }: { person: string; balance: number; close: () => void; save: (x: LedgerEntry) => void }) { const [amount, setAmount] = useState(Math.abs(balance)); const action = balance > 0 ? 'دریافت کردم' : 'پرداخت کردم'; const kind: LedgerEntry['kind'] = balance > 0 ? 'payable' : 'receivable'; return <div className="fixed inset-0 z-40 grid place-items-center bg-slate-950/45 p-3"><div className="w-full max-w-sm rounded-2xl bg-white p-5 dark:bg-[#162235]"><div className="flex justify-between"><b>ثبت تسویه با {person}</b><button onClick={close}><X /></button></div><p className="mt-3 text-sm text-slate-500">با ثبت مبلغ، ماندهٔ این شخص به‌صورت تجمعی اصلاح می‌شود.</p><div className="mt-4"><b className="text-sm">{action}</b><NumericInput value={amount} onChange={setAmount} /></div><button data-testid="confirm-settlement" disabled={amount <= 0} onClick={() => save({ id: uid(), person, kind, amount, date: today(), notes: `تسویه: ${action}`, movement: balance > 0 ? 'received' : 'paid', settled: false })} className="mt-5 min-h-11 w-full rounded-xl bg-[#1769c2] text-white disabled:opacity-50">ثبت تسویه</button></div></div>; }
function SettingsPanel({ settings, save, close, exportExcel, pick, preview, cancel, restore, loans }: { settings: AppSettings; save: (s: AppSettings) => void; close: () => void; exportExcel: () => void; pick: () => void; preview: SavedState | null; cancel: () => void; restore: (m: boolean) => void; loans: Loan[] }) { const [draft, setDraft] = useState(settings); const googleCalendar = () => { const events = loans.flatMap(l => l.installments.filter(i => i.status !== 'paid').map(i => `BEGIN:VEVENT\nDTSTART;VALUE=DATE:${i.dueDate.replaceAll('-', '')}\nSUMMARY:${l.name} - قسط ${i.number}\nDESCRIPTION:${money(i.amount)}\nEND:VEVENT`)).join('\n'); const blob = new Blob([`BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//Asemanian//FA\n${events}\nEND:VCALENDAR`], { type: 'text/calendar;charset=utf-8' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'asemanian-installments.ics'; a.click(); URL.revokeObjectURL(a.href); }; return <div className="fixed inset-0 z-40 overflow-y-auto bg-slate-950/45 p-3"><div className="mx-auto my-5 w-full max-w-lg rounded-2xl bg-white p-5 dark:bg-[#162235]"><div className="flex justify-between"><b>تنظیمات</b><button onClick={close}><X /></button></div><label className="mt-5 block text-sm">حالت نمایش<select value={draft.theme} onChange={e => setDraft({ ...draft, theme: e.target.value as AppSettings['theme'] })} className="mt-1 min-h-11 w-full rounded-xl bg-slate-100 px-3 dark:bg-slate-800"><option value="light">روشن</option><option value="dark">تیره</option><option value="system">پیش‌فرض دستگاه</option></select></label><label className="mt-4 block text-sm">تاریخ دوم در تقویم<select value={draft.calendarKind} onChange={e => setDraft({ ...draft, calendarKind: e.target.value as CalendarKind })} className="mt-1 min-h-11 w-full rounded-xl bg-slate-100 px-3 dark:bg-slate-800"><option value="jalali">نمایش نده</option><option value="gregorian">میلادی</option><option value="lunar">هجری قمری</option></select></label><div className="mt-5"><b>تقویم گوگل</b><p className="mt-1 text-sm text-slate-500">فایل تقویم اقساط را دریافت و در Google Calendar وارد کنید.</p><button data-testid="google-calendar-export" onClick={googleCalendar} className="mt-3 min-h-11 rounded-xl bg-slate-800 px-4 text-white">دریافت فایل تقویم</button></div><div className="mt-5 flex flex-wrap gap-2"><button data-testid="export-backup" onClick={exportExcel} className="flex items-center gap-2 rounded-xl bg-[#1769c2] px-4 py-3 text-white"><Download size={17} />پشتیبان اکسل</button><button data-testid="import-backup" onClick={pick} className="flex items-center gap-2 rounded-xl bg-slate-800 px-4 py-3 text-white"><FileUp size={17} />بازیابی اکسل</button></div><p className="mt-2 text-xs leading-6 text-slate-500">محل ذخیره فایل را تنظیمات دانلود مرورگر یا دستگاه تعیین می‌کند؛ برنامه نمی‌تواند پوشه دلخواه را درخواست کند.</p>{preview && <div className="mt-4 rounded-xl bg-blue-50 p-4 dark:bg-blue-950"><b>{num(preview.loans.length)} وام و {num(preview.ledger.length)} گردش دفتر آمادهٔ بازیابی است</b><div className="mt-3 flex gap-2"><button data-testid="restore-replace" onClick={() => restore(false)} className="rounded-lg bg-[#1769c2] px-3 py-2 text-sm text-white">جایگزینی</button><button data-testid="restore-merge" onClick={() => restore(true)} className="rounded-lg bg-emerald-600 px-3 py-2 text-sm text-white">ادغام</button><button onClick={cancel} className="rounded-lg bg-white px-3 py-2 text-sm dark:bg-slate-800">انصراف</button></div></div>}<div className="mt-6 flex gap-3 border-t pt-4"><button data-testid="save-settings" onClick={() => save(draft)} className="min-h-11 flex-1 rounded-xl bg-[#1769c2] font-bold text-white">ذخیره</button><button data-testid="settings-back" onClick={close} aria-label="بازگشت" className="grid size-11 place-items-center rounded-full bg-slate-100 hover:bg-slate-200 dark:bg-slate-800"><CornerUpRight size={20} className="rotate-180" /></button></div></div></div>; }
